export const BODY: string = "\n<p>حدث لكل مصمم: يرى لونًا على الشاشة ويريد كوده الدقيق: لقطة شاشة أو صورة أو شعار أو نموذج قد تحمل النغمة المثالية، لكن تخمين قيمتها لا يعمل أبدًا.</p>\n<p>منتقي ألوان الصورة يحل تلك المشكلة في ثوانٍ: تفتح صورة وتشير إلى أي بكسل وتقرأ كود لونه الدقيق في HEX وRGB وHSL وCMYK.</p>\n<p>في هذا الدليل نشرح كيف يعمل <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a> من CompressMyPic، وماذا يعني كل كود لون، وكيف تستخدم الألوان المختارة في عمل تصميم وتطوير حقيقي.</p>\n<h2 id=\"what-is-an-image-color-picker\">ما منتقي ألوان الصورة؟</h2>\n<p>منتقي ألوان الصورة أداة متصفح تقرأ لون أي بكسل من صورة ترفعها: يعمل كقطارة برنامج تصميم، لكن دون تثبيت.</p>\n<p>تسحب صورة أو لقطة شاشة إلى الأداة وتحرك المؤشر فوق الصورة، وتعرض الأداة اللون الموجود في تلك النقطة بالضبط: وتتحدث القيمة مباشرة أثناء تحريك المؤشر. وتقبل الأداة صيغ صور الأكثر شيوعًا، مثل JPG وPNG وWebP وGIF: وتدعم ملفات حتى 20 MB، ما يغطي تقريبًا أي صورة أو شعار أو لقطة شاشة قد تحتاجها.</p>\n<p>وتُعالج كلها محليًا في متصفحك: صورتك لا تُرفع أبدًا إلى أي خادم، فتبقى نماذج العملاء وعمل العلامة غير المنشور خاصة أثناء عملك عليها.</p>\n<h2 id=\"how-the-eyedropper-reads-a-pixel\">كيف تقرأ القطارة بكسلًا</h2>\n<p>كل صورة رقمية شبكة مربعات صغيرة تسمى بكسلات: كل بكسل يحفظ لونًا، موصوفًا بثلاثة أرقام تقابل الضوء الأحمر والأخضر والأزرق.</p>\n<p>عندما تنقر نقطة في الصورة، تقرأ الأداة قيم الأحمر والأخضر والأزرق لذلك البكسل: ثم تحوّل تلك الأرقام الثلاثة إلى كل صيغ الألوان التي قد تحتاجها. والقراءة دقيقة لا تقدير: البكسل فعلًا ذلك اللون، والكود الذي تنسخه سيعيد إنتاجه بأمانة في ملف تصميم أو ورقة أنماط أو وثيقة للطباعة.</p>\n<p>لكن بكسلًا واحدًا قد يفاجئك: في صورة، البكسلات المجاورة غالبًا تختلف قليلًا، فتحريك خطوة إلى الجانب قد يغيّر الرقم الأخير من كود HEX.</p>\n<h2 id=\"color-codes-explained\">أكواد الألوان التي تحصل عليها: HEX وRGB وHSL وCMYK</h2>\n<p>كل بكسل تختاره ينتج عدة أكواد لون معًا: HEX هو الكود المكون من ستة أرقام الذي يستخدمه مطورو الويب في CSS، مثل #2563EB لأزرق شديد.</p>\n<p>RGB يصف نفس اللون بثلاثة أرقام من 0 إلى 255، واحد للأحمر وواحد للأخضر وواحد للأزرق: إنه الصيغة التي تستخدمها معظم أدوات التصميم ومحررات الصور. وHSL يصف اللون بالدرجة والتشبع والإضاءة: يحبه المصممون لأنه يطابق طريقة تفكير الناس في اللون: اختر درجة ثم اجعلها أكثر شدة أو أكثر خفوتًا.</p>\n<p>وCMYK يصف اللون كنسب حبر للطباعة: إنه تقريب على الشاشة، لأن الشاشات تستخدم ضوءًا والطابعات تستخدم حبرًا، لكنه نقطة بداية جيدة لعمل الطباعة.</p>\n<h2 id=\"the-11x11-loupe\">عدسة 11 في 11: لماذا يهم التكبير</h2>\n<p>اختيار البكسل الصحيح صعب بالتكبير العادي: خط رفيع أو أيقونة صغيرة أو حد بكسل واحد قد يُفوت بشعرة، وخطأ يعطيك اللون الخطأ.</p>\n<p>تحل الأداة هذا بعدسة مكبرة 11 في 11: تُظهر عرضًا مكبرًا للبكسلات حول المؤشر، فترى بالضبط أي بكسل أنت على وشك أخذه. والعدسة مفيدة خاصة للقطات شاشة الواجهات: الأزرار والخطوط الفاصلة والنص غالبًا تقع على حواف منعمّة، حيث يمتزج اللون على بكسلين أو ثلاثة.</p>\n<p>وبالتكبير، تستطيع استهداف المركز الصلب لشكل بدل حافته الممزوجة: ذلك القرار وحده غالبًا الفرق بين لون العلامة الحقيقي ونغمة وسطية تنتمي إلى لا شيء.</p>\n<h2 id=\"picked-swatches\">عينات مختارة: كيف تبني مجموعة</h2>\n<p>لون واحد نادرًا يكفي: لوحة علامة أو سمة موقع أو عرض تقديمي تحتاج عدة ألوان تعمل معًا، والأداة تتيح لك جمعها واحدًا واحدًا.</p>\n<p>كل نقرة تضيف اللون المأخوذ إلى درج \"عينات مختارة\": تستطيع جمع اللون الرئيسي واللمسة والخلفية ولون النص من نفس الصورة. وتبقى العينات مرئية أثناء عملك، فتستطيع مقارنتها جنبًا إلى جنب: وإذا بدت اختيارين شبه متطابقين، تستطيع التخلص من واحدة والاحتفاظ بالنسخة الأنظف.</p>\n<p>والنقر مرتين على نفس قيمة HEX لا يخلق مكررًا: تحافظ الأداة على مجموعتك مرتبة، ما يهم عندما تأخذ عينات من صورة بنغمات شبه متطابقة كثيرة.</p>\n<h2 id=\"export-css\">تصدير CSS: من الصورة إلى ورقة الأنماط</h2>\n<p>العينات المجمعة تنفع فقط إذا استطعت نقلها إلى مشروعك: زر \"تصدير CSS\" ينزّل الألوان المختارة كخصائص مخصصة لـCSS، جاهزة للاستخدام.</p>\n<p>التنزيل يعطيك متغيرات مثل --color-1 و--color-2 وهكذا، كل منها بقيمة HEX: تستطيع لصقها في ورقة أنماط واستخدامها في أي مكان في تصميمك. وهذا أفضل من نسخ الأكواد واحدًا واحدًا في ملف نصي: التصدير يحافظ على كل الألوان في مكان واحد، بالترتيب الصحيح ودون أخطاء نسخ.</p>\n<p>ولسير لوحة أكثر اكتمالًا، <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصور</a> يبني لوحة مرتبة تلقائيًا: استخدم المنتقي عندما تريد بكسلات دقيقة والمستخرج عندما تريد مخططًا كاملًا.</p>\n<h2 id=\"picking-colors-from-photos\">كيف تأخذ ألوانًا من صور</h2>\n<p>الصور هي المصدر الأكثر شيوعًا للألوان المختارة: غروب أو صورة منتج أو صورة سفر قد تعطي لوحة كاملة تبدو طبيعية معًا أصلًا.</p>\n<p>ابدأ بالمناطق المسطحة الأكبر في الصورة: سماء صافية أو جدار مطلي أو قطعة ملابس تعطي لونًا ثابتًا يُؤخذ أفضل من ملمس مزدحم. وتجنب أشد الإضاءات وأعمق الظلال: تلك المناطق غالبًا مقصوصة، ما يعني أن معلومات اللون الحقيقية فُقدت والكود الذي تحصل عليه مجرد أبيض أو أسود نقي.</p>\n<p>خذ عينات من نفس المنطقة مرات عدة وقارن النتائج: إذا تجمعت الأكواد حول قيمة، فتلك القيمة هي لون السطح الحقيقي. وإذا تبعثرت، اختر الوسط من المجموعة.</p>\n<h2 id=\"picking-colors-from-logos-and-screenshots\">كيف تأخذ ألوانًا من شعارات ولقطات شاشة</h2>\n<p>الشعارات ولقطات شاشة الواجهات هي حالة الدقة: لون علامة يجب أن يطابق بالضبط، لأن نغمة قريبة تبدو سيئة بجانب الشعار الحقيقي.</p>\n<p>للشعارات، خذ عينات من مركز شكل مسطح وكبير: مركز حرف أو كتلة صلب، بينما الحواف تمتزج مع الخلفية وتعطي قيمًا ممزوجة. وللقطات الشاشة، الصق مباشرة بـCtrl+V عندما تستطيع: تقبل الأداة صورًا من الحافظة، فتستطيع التقاط الشاشة وأخذ عينات منها دون حفظ ملف.</p>\n<p>وعند أخذ عينات من لقطة شاشة، راجع إحداثيات البكسل التي يعرضها فاحص البكسل: الإحداثيات تساعدك على العودة إلى نفس النقطة بالضبط إذا احتجت التحقق من قيمة لاحقًا.</p>\n<h2 id=\"color-accuracy-jpeg-transparency\">دقة اللون: ضجيج JPEG والشفافية</h2>\n<p>ضغط JPEG يغيّر ألوان البكسل قليلًا: الصيغة تحفظ الألوان في كتل صغيرة، فبكسلان متجاوران في سماء موحدة قد يختلفان برقم أو رقمين.</p>\n<p>هذا التباين طبيعي ولا يؤثر في معظم الأعمال: اختر القيمة التي تظهر أكثر في المنطقة وستبدو النتيجة جيدة للعين. وملفات PNG تتصرف بشكل آخر: PNG يحفظ الألوان الدقيقة، فالكود الذي تقرأه هو الكود الذي يحتويه الملف، دون أي ضجيج ضغط.</p>\n<p>والمناطق الشفافة تحتاج عناية: عند أخذ عينة من جزء شفاف من شعار PNG، يُقرأ اللون الموجود تحت الشفافية، وقد يكون أبيض أو أسود بدل اللون الذي تتوقعه.</p>\n<h2 id=\"picking-colors-on-mobile\">كيف تأخذ ألوانًا على الهاتف والشاشات اللمسية</h2>\n<p>منتقي الألوان يعمل أيضًا على هواتف وأجهزة لوحية، تمامًا كما على الحاسوب: تلمس الصورة بدل النقر، وتنطبق نفس ميزات العدسة والعينات.</p>\n<p>اللمس أقل دقة من الفأرة، لأن طرف إصبعك يغطي بكسلات كثيرة معًا: العدسة المكبرة تهم أكثر هنا، لأنها تُظهر ما تحت إصبعك. وكبّر الصورة في متصفحك قبل اللمس إذا كان الهدف صغيرًا: صورة أكبر تعطي إصبعك هدفًا أكبر وتقلل احتمال أخذ بكسل مجاور.</p>\n<p>ولألوان علامة حرجة، تحقق من الاختيار لاحقًا على حاسوب: لمسة على الهاتف تقربك، لكن نقرة فأرة على البكسل الدقيق هي التحقق النهائي الموثوق.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند أخذ ألوان</h2>\n<p>أكثر خطأ شيوعًا أخذ عينة من حد بدل منطقة مسطحة: الحواف المنعمّة تمزج لونين، والقيمة الممزوجة لا تنتمي إلى أي منهما.</p>\n<p>خطأ آخر الثقة بنقرة واحدة في صورة بها ضجيج: بكسل في صورة محببة قد يكون حالة شاذة، فخذ عينات من نفس النقطة مرتين أو ثلاثًا دائمًا. وينسى الناس أيضًا أن الشاشات تختلف: نفس كود HEX قد يبدو مختلفًا قليلًا على شاشتين، فاحكم على لون بكوده لا بمظهره على شاشتك فقط.</p>\n<p>وأخيرًا، لا تأخذ عينات من لقطة شاشة للقطة أخرى: كل التقاط وكل حفظ قد يغيّر الألوان قليلًا، فاعمل دائمًا مع أنظف ملف أصلي.</p>\n<h2 id=\"color-picker-vs-palette-extractor\">منتقي الألوان مقابل مستخرج اللوحة</h2>\n<p>منتقي الألوان ومستخرج اللوحة يجيبان سؤالين مختلفين: المنتقي يخبرك اللون الدقيق لبكسل تختاره، بينما المستخرج يجد الألوان المهيمنة لصورة كاملة.</p>\n<p>استخدم المنتقي عندما تعرف ما تريد: الأزرق الدقيق لشعار أو النغمة الدقيقة لزر أو الظل الدقيق لجدار في صورة. واستخدم المستخرج عندما تريد أفكارًا: الألوان الخمسة أو الستة التي تحدد صورة، مرتبة حسب كم من الصورة تغطي: إنها أسرع طريق إلى لوحة كاملة.</p>\n<p>كثير من المصممين يستخدم الاثنين: يستخرجون لوحة للمخطط العام ثم يستخدمون المنتقي لأخذ لون لمسة دقيق وضعه المستخرج منخفضًا جدًا ليشمله.</p>\n<h2 id=\"who-uses-a-color-picker\">من يستخدم منتقي ألوان الصورة؟</h2>\n<p>مطورو الويب يستخدمونه لمطابقة نموذج تصميم بالضبط: عندما يرسل عميل لقطة شاشة بدل ملف تصميم، يستعيد المنتقي أكواد HEX.</p>\n<p>ومصممو الغرافيك يستخدمونه لبناء لوحات من صور مرجعية: صورة من لوحة مزاج قد تعطي مخطط ألوان كاملًا لملصق أو هوية علامة. ومصممو الطباعة يستخدمون قراءة CMYK كنقطة بداية: ليست مطابقة مثالية للطباعة، لكنها تخبرهم إن كان لون شاشة ساطع سينجو على الورق.</p>\n<p>وصناع المحتوى يستخدمونه لمصغرات ورسوم وسائل التواصل الاجتماعي: مطابقة لمسة مصغرة مع لون العلامة تحافظ على مظهر القناة متسقًا عبر عشرات الفيديوهات.</p>\n<h2 id=\"privacy-in-your-browser\">خصوصية: صورك تبقى في متصفحك</h2>\n<p>الخصوصية تهم عندما تكون الصورة نموذج عميل أو صورة منتج غير منشور أو صورة شخصية: رفع تلك الملفات إلى أي خادم خطر لا تحتاجه.</p>\n<p>هذه الأداة تعالج كل شيء محليًا: الصورة يقرأها متصفحك، والبكسلات تُؤخذ على جهازك، ولا يخرج شيء من حاسوبك. وهذا يعني أيضًا أن الأداة تعمل دون اتصال بمجرد تحميل الصفحة: تستطيع أخذ عينات ألوان في طائرة أو غرفة اجتماعات أو أي مكان دون اتصال.</p>\n<p>وإذا تعاملت مع أصول علامة حساسة، فالمعالجة المحلية هي الميزة الحاسمة: بلا رفع لا توجد أي نسخة من الملف على خادم لا تتحكم فيه.</p>\n<h2 id=\"sampling-gradients-and-patterns\">كيف تأخذ عينات ألوان من تدرجات وأنماط</h2>\n<p>التدرجات حالة خاصة، لأن اللون يتغير بسلاسة من طرف إلى آخر: لا يوجد لون واحد صحيح في تدرج، فقط لون النقطة الدقيقة التي تأخذها.</p>\n<p>لالتقاط تدرج، خذ عينات من عدة نقاط على امتداده: خذ لون البداية والوسط والنهاية، وتستطيع إعادة بناء التدرج في CSS بتلك المحطات الثلاث. والأنماط تحتاج نفس العناية: سطح مخطط أو مربعات يحتوي لونين على الأقل، والمنتقي يقرأ فقط البكسل الموجود تحت المؤشر، لا النمط كله.</p>\n<p>ولنمط، خذ عينات من كل شريط مميز على حدة واحفظها كلها كعينات: مجموعة العينات تصف النمط بعدها، مع أن لا نقرة وحدها تستطيع فعل ذلك.</p>\n<p>والأسطح ذات الملمس، مثل الخشب والقماش والحجر، هي أصعب حالة: لونها يختلف من بكسل إلى بكسل، فقراءة واحدة لا تعني شيئًا تقريبًا.</p>\n<p>مع الملمس، خذ عينات من خمسة أو ستة بكسلات قريبة وابحث عن المتوسط: القيمة الأكثر شيوعًا في المجموعة هي أفضل تمثيل لذلك السطح، وستبدو جيدة في تصميمك.</p>\n<h2 id=\"how-to-use-the-tool\">كيف تستخدم منتقي ألوان الصورة</h2>\n<p>افتح <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a> في متصفحك: اسحب صورتك إلى منطقة الرفع أو الصق لقطة شاشة مباشرة من الحافظة.</p>\n<p>يظهر لون افتراضي بمجرد تحميل الصورة، مأخوذ من مركز الصورة: حرّك المؤشر للاستكشاف وراقب كيف تكبّر العدسة البكسلات تحت مؤشرك.</p>\n<p>انقر أي بكسل لإضافته إلى \"عينات مختارة\": استمر في النقر لجمع كل الألوان التي تحتاجها لتصميمك.</p>\n<p>وعندما تكتمل مجموعتك، انقر \"تصدير CSS\" لتنزيل الألوان كمتغيرات ورقة أنماط: ثم اقرأ النسخة خطوة بخطوة في <a href=\"/ar/blog/kayfiyya-ikhtiyar-lawn-min-as-sura/\">كيف تختار لونًا من صورة</a>، أو تعلم صيغ الألوان في <a href=\"/ar/blog/hex-vs-rgb-vs-hsl/\">HEX مقابل RGB مقابل HSL: أكواد الألوان موضحة</a>. وللوحة كاملة تلقائية، استخدم <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين اختيار لون واستخراج لوحة؟","answer":"عند الاختيار، تقرأ بكسلًا دقيقًا تختاره، فتتحكم بدقة في اللون الذي تحصل عليه: وعند الاستخراج، تمسح الأداة الصورة كلها وترتب ألوانها الأكثر شيوعًا تلقائيًا. واستخدم المنتقي لدقة، والمستخرج لأفكار لوحة كاملة."},{"question":"لماذا تعطي نقرتان في نفس المنطقة كودي HEX مختلفين قليلًا؟","answer":"في الصور، البكسلات المجاورة نادرًا متطابقة بسبب ضجيج الكاميرا وضغط JPEG: كل بكسل له لونه الخاص، فتحريك بكسل إلى الجانب قد يغيّر الرقم الأخير. وخذ عينات من نفس النقطة مرات عدة واختر القيمة الأكثر شيوعًا."},{"question":"هل أستطيع استخدام الألوان المختارة مباشرة في ورقة أنماط موقع؟","answer":"نعم، زر \"تصدير CSS\" ينزّل عيناتك كخصائص مخصصة لـCSS بقيم HEX: الصقها في ورقة أنماطك واستخدم المتغيرات حيث تحتاج ذلك اللون. وأكواد HEX تعمل أيضًا في Figma وCanva ومعظم أدوات التصميم."},{"question":"هل يغيّر منتقي الألوان صورتي أو يضغطها؟","answer":"لا، الأداة تقرأ قيم البكسل فقط ولا تعدّل أو تعيد حفظ أو تضغط ملفك أبدًا: صورتك الأصلية تبقى سليمة، وتستطيع إغلاق الصفحة وأنت تعرف أن الملف على جهازك لم يتغير."},{"question":"كيف آخذ لونًا من موقع لا أستطيع تنزيل صورة منه؟","answer":"خذ لقطة شاشة للصفحة ثم الصقها في الأداة بـCtrl+V أو ارفع ملف اللقطة: يقرأ المنتقي بكسلات اللقطة مثل أي صورة أخرى، فتستطيع أخذ أي لون تراه على الشاشة."},{"question":"ماذا أفعل إذا بدا اللون الذي اخترته مختلفًا في أداة تصميمي؟","answer":"تحقق أولًا من نسخ كود HEX الكامل، دون فقدان أي رقم: ثم تذكر أن الشاشات وملفات الألوان تختلف، فنفس الكود قد يبدو مختلفًا قليلًا على شاشتين. واحكم على اللون بكوده، وقارن على نفس الشاشة عندما يهم التطابق."}];
